"""Whole minutes and seconds for one mile."""

def mile_pace(distance_miles, elapsed_seconds):
    if distance_miles <= 0 or elapsed_seconds < 0:
        return (0, 0)
    per_mile = int(elapsed_seconds / distance_miles)
    minutes, seconds = divmod(per_mile, 60)
    return (minutes, seconds)

"""Cans of paint for one wall, rounding up."""

def paint_cans(width_ft, height_ft, coverage_sqft):
    if width_ft <= 0 or height_ft <= 0 or coverage_sqft <= 0:
        return 0
    area = width_ft * height_ft
    return (area + coverage_sqft - 1) // coverage_sqft

"""Bicycle gear inches from wheel size and the gear pair."""

def gear_inches(wheel_in, chainring, cog):
    if wheel_in <= 0 or chainring <= 0 or cog <= 0:
        return 0
    return (wheel_in * chainring) // cog

"""Inside opening of a picture mat after the border is removed."""

def mat_opening(frame_w, frame_h, border):
    if frame_w <= 0 or frame_h <= 0 or border < 0:
        return (0, 0)
    opening_w = frame_w - 2 * border
    opening_h = frame_h - 2 * border
    if opening_w < 1 or opening_h < 1:
        return (0, 0)
    return (opening_w, opening_h)

"""True when a digit string passes the Luhn check."""

def doubled_digit(value):
    doubled = value * 2
    if doubled > 9:
        return doubled - 9
    return doubled

def luhn_ok(digits):
    if not digits:
        return False
    total = 0
    for index, ch in enumerate(reversed(digits)):
        if ch < "0" or ch > "9":
            return False
        value = ord(ch) - 48
        if index % 2 == 1:
            value = doubled_digit(value)
        total += value
    return total % 10 == 0

"""Grams of coffee for a water dose at a given ratio."""

def coffee_grams(water_grams, parts_water):
    if water_grams <= 0 or parts_water <= 0:
        return 0
    return water_grams // parts_water

"""Riser count so each step stays at or under the target height."""

def riser_count(total_rise_in, target_riser_in):
    if total_rise_in <= 0 or target_riser_in <= 0:
        return 0
    return (total_rise_in + target_riser_in - 1) // target_riser_in

"""NWS wind chill in Fahrenheit, or the air temperature when it does not apply."""

def chill_factor(wind_mph):
    return wind_mph ** 0.16

def wind_chill_f(temp_f, wind_mph):
    if wind_mph <= 3 or temp_f > 50:
        return temp_f
    factor = chill_factor(wind_mph)
    chill = 35.74 + (0.6215 * temp_f) - (35.75 * factor) + (0.4275 * temp_f * factor)
    return round(chill, 1)
